import React from "react";
import { useSelector } from "react-redux";

const Profile = () => {
  const { currentUser } = useSelector((state) => state.user);
  return (
    <div className="p-3 max-w-lg mx-auto">
      <h1 className="tet-3xl font-semiboald text-center my-7">Profile</h1>
      <form className="flex flex-col gap-4">
        <img
          className="h-24 w-24 self-center cursor-pointer rounded-full object-cover"
          src={currentUser.profilepicture}
          alt="profile"
        />
         <input type="text" id="username" placeholder="UserName" className="bg-slate-100 rounded-lg p-3"/>
         <input type="email" id="email" placeholder="Email" className="bg-slate-100 rounded-lg p-3"/>
         <input type="Password" id="passw" placeholder="UserName" className="bg-slate-100 rounded-lg p-3"/>
      
      </form>
    </div>
  );
};

export default Profile;
